INSERT INTO public.risk_definitions (risk_key, plain_name, methodology_anchor, definition, evidence_signals, evidence_types, severity_rubric, example, active)
VALUES
('budget_unidentified', 'No budget established', 'MEDDPICC: Metrics/EB; BANT: Budget', 'No statement exists about budget existence, amount, or funding intent for this purchase.', 'GAP: budget field Unknown after a call where budget was discussable (QDC+). STATED: ''there''s no budget for this'' (quote-backed, severity higher).', ARRAY['stated','gap']::text[], 'High if past discovery with no budget statement; Critical if stated no-budget with no funding path; Medium pre-QDC.', 'Three calls in, budget=Unknown -> gap risk: ''Budget has not been discussed.''', true),
('budget_not_allocated', 'Budget not approved', 'MEDDPICC: EB; BANT: Budget', 'An amount or intent exists but no approval/allocation: ''we figure around $100k'' without sign-off.', 'STATED: budget text present, budget_allocated=false from the prospect''s own framing (estimate/hope language).', ARRAY['stated']::text[], 'Medium with strong CE (funding follows pain); High if decision_date inside 60 days with no allocation.', 'Quote: ''We''d have to go ask the board'' -> allocated=false; risk: approval step unowned.', true),
('eb_unidentified', 'Economic buyer unknown', 'MEDDPICC: Economic Buyer; Po7 stakeholder map', 'No quote-backed evidence identifies who controls the spend. Title guesses are hypotheses, not identification.', 'GAP: is_economic_buyer=false on all contacts after discovery-stage calls.', ARRAY['gap']::text[], 'Medium in discovery; High at solution_validation+; Critical at selection.', 'Five contacts, none evidenced as EB at confirming_value -> gap risk.', true),
('eb_no_access', 'No access to power', 'MEDDPICC: EB; Po7: access to power', 'EB is identified but the rep has never spoken with them and no path is established.', 'GAP: EB named in deal_analysis but appears in no conversation participant list and no meeting is scheduled. STATED: ''you won''t need to talk to Senake'' (blocked access, higher severity).', ARRAY['stated','gap']::text[], 'High by default; Critical if champion resists creating access (blocked-access quote).', 'EB named in QDC, absent from every call since, no scheduled touch -> gap risk: power untouched.', true),
('authority_misread', 'Authority unclear or misread', 'MEDDPICC: EB/DP; Sandler', 'Decision authority claims conflict: contact claims the call is theirs while signer/approval evidence points elsewhere.', 'STATED: conflicting quotes across contacts/calls about who decides (rule 9 conflict capture feeds this).', ARRAY['stated']::text[], 'High; Critical when the believed decider is the only thread (compound with single_threaded).', 'Controller: ''it''s my decision''; later CFO: ''I''ll be making the final call'' -> conflict risk with both quotes.', true),
('champion_absent', 'No champion', 'MEDDPICC: Champion; Po7', 'No contact shows quote-backed champion behaviors (internal selling, access creation, inside information, personal win).', 'GAP: no is_champion=true after discovery. Candidate enthusiasm without behaviors stays a hypothesis, and the risk stands.', ARRAY['gap']::text[], 'Medium in discovery; High at solution_validation+.', 'Engaged controller, zero champion behaviors evidenced -> gap risk + hypothesis row for the candidate.', true),
('champion_untested', 'Champion untested', 'Po7: champion testing; Black Swan', 'Champion behaviors exist but the champion has never been asked to DO something that proves influence (set the EB meeting, share the budget process).', 'GAP: is_champion=true but no completed champion-action task (EB meeting created, internal doc shared) in deal history.', ARRAY['gap']::text[], 'Medium; High entering selection (untested champions fail at the close).', 'Champion ''loves it'' for 6 weeks; no EB meeting ever materialized -> untested.', true),
('pain_unquantified', 'Pain not quantified', 'MEDDPICC: Metrics; SPIN', 'Pains exist but none carry dollars/hours: the ROI case has no prospect-stated numbers.', 'GAP: deal_pain_points rows with empty annual_cost AND annual_hours across all pains; deal_metrics has no pain-linked observations.', ARRAY['gap']::text[], 'Medium in discovery; High at confirming_value (ROIBuilder will cite benchmarks, not their numbers: weaker close).', 'Four pains captured, zero quantified after FDC -> gap risk + quantifying-question coaching note.', true),
('pain_operations_rooted', 'Pain not finance-rooted', 'Sage spine: Finance-Operations Orientation', 'The driving pains are operations-rooted rather than finance-rooted: per Sage canon this is a fit/championing risk (finance must own the buy).', 'STATED: pain rows'' affected_team/category skew operations with no finance-stated pains.', ARRAY['stated']::text[], 'High per the qualifying spine; compounds with eb/champion gaps in finance.', 'All pains from the ops director, finance silent across calls -> orientation risk.', true),
('compelling_event_missing', 'No compelling event', 'Sage spine; MEDDPICC: Identify Pain', 'No consequence-of-inaction exists: nothing bad happens if they do nothing.', 'GAP: zero compelling_events rows (existing QDC HIGH RISK rule, now a standing risk). STATED: ''no real deadline'' (quote, higher confidence in the risk).', ARRAY['stated','gap']::text[], 'High always; Critical inside a committed forecast category (commit/forecast with no CE is a forecast integrity problem).', 'Deal in ''forecast'' with zero CE rows -> critical risk, surfaces in PipelineIQ.', true),
('catalyst_missing', 'No driving catalyst', 'Sage spine', 'Nothing is actively driving change: no acquisition, growth, leadership change, or system event pushing them.', 'GAP: zero business_catalysts rows after discovery.', ARRAY['gap']::text[], 'High; combined CE+catalyst+orientation all missing = ''deal isn''t real yet'' flag (computable spine rule).', 'No catalysts after QDC+FDC -> risk; spine flag if CE also missing.', true),
('timing_slippage', 'Timeline slipping or vague', 'BANT: Timing; JOLT (indecision)', 'Stated dates moved later across calls, or milestone dates remain Unknown deep into the process. JOLT lens: slippage without cause is indecision, not delay.', 'STATED: changed_fact history on timeline fields moving outward (change-aware recency makes this computable). GAP: all four dates Unknown at solution_validation+.', ARRAY['stated','gap']::text[], 'Medium on first slip with stated cause; High on second slip or causeless slip; High for date vacuum late-stage.', 'signature_date moved Oct -> Dec -> ''early next year'' across three calls -> slippage risk with the change history as evidence.', true),
('criteria_undefined', 'Decision criteria undefined', 'MEDDPICC: Decision Criteria', 'No stated standards for how vendors will be judged: the deal can be lost to criteria written by someone else.', 'GAP: zero deal_decision_criteria rows after discovery.', ARRAY['gap']::text[], 'Medium in discovery; High at selection.', 'Entering demos with no stated criteria -> risk + coaching note to co-author criteria.', true),
('criteria_competitor_shaped', 'Criteria favor a competitor', 'MEDDPICC: DC + Competition', 'Stated criteria mirror a specific competitor''s strengths (suite breadth, single-vendor preference), suggesting someone is shaping the eval.', 'STATED: criteria quotes that match a named competitor''s known positioning, especially appearing after that competitor''s demo.', ARRAY['stated']::text[], 'High; Critical if the criterion is a stated must-have we cannot meet.', 'Post-NetSuite demo: ''we''ve decided we want CRM and ERP from one vendor'' -> competitor-shaped criterion risk.', true),
('decision_process_unknown', 'Decision process unknown', 'MEDDPICC: Decision Process', 'No stated steps for how the evaluation proceeds: surprises (committees, IT review) appear late.', 'GAP: decision_process empty after discovery-stage calls.', ARRAY['gap']::text[], 'Medium mid-funnel; High at selection.', 'confirming_value with no process map -> risk.', true),
('paper_process_unknown', 'Paper process unknown', 'MEDDPICC: Paper Process', 'Contracting reality undiscovered: legal review, procurement, security review, MSA redlines. The classic late-stage timeline killer.', 'GAP: no statements about legal/procurement/security captured by selection stage. STATED: ''legal takes a while here'' uncaptured in plan (quote raises severity).', ARRAY['stated','gap']::text[], 'Medium at solution_validation; High at selection; Critical when signature_date is inside 30 days with paper process unknown.', 'Verbal yes, signature in 3 weeks, nobody has mentioned legal -> critical paper risk.', true),
('competition_incumbent_bias', 'Competitive bias at power', 'MEDDPICC: Competition; Po7', 'A power-position stakeholder has stated preference or history with a competitor.', 'STATED: bias quotes (''our CFO came from a NetSuite shop''), prior_bias on deal_competitors, competitor-praise from EB/signer.', ARRAY['stated']::text[], 'High when at EB/signer; Medium at influencer level.', 'Chaberton pattern: ''Campfire''s number is hard to ignore'' from the CFO -> stated bias + price-pressure compound.', true),
('competition_price_pressure', 'Price-led competition', 'Competition; JOLT (safe-cheap option)', 'A competitor is winning the value frame on price; prospect statements anchor on cost difference rather than capability.', 'STATED: price-comparison quotes, ''they''re half the cost'', budget statements re-anchored to competitor pricing after their proposal.', ARRAY['stated']::text[], 'Medium with strong quantified pain (value case can win); High with pain_unquantified (nothing to weigh against price).', 'Quote: ''Hard to justify double for the same checkboxes'' -> price-frame risk; severity High because pains are unquantified.', true),
('single_threaded', 'Single-threaded deal', 'Po7: stakeholder mapping', 'All evidence flows through one contact: every conversation, every fact, one thread. Champion loss or vacation stalls the deal.', 'GAP: computable from participants across conversations + contacts with engagement (one unique prospect participant across N calls).', ARRAY['gap']::text[], 'Medium at 2+ calls single-threaded; High at solution_validation+; compounds with champion_untested and authority risks.', 'Four calls, Keith is the only prospect voice ever -> single-thread risk (Chaberton watch item).', true),
('consultant_gatekeeper', 'Consultant controls access', 'Po7; Sandler (gatekeeper)', 'A third-party advisor mediates all contact and information; rep has no direct line to the buying team''s power.', 'STATED: has_consultant=true + statements routing contact through the advisor (''send everything through Sarah'').', ARRAY['stated']::text[], 'Medium when consultant is engaged and neutral; High when direct contact is explicitly blocked.', 'Quote: ''Sarah will collect all vendor responses, please don''t contact the team directly'' -> gatekeeper risk.', true),
('functional_gap', 'Stated requirement with uncertain fit', 'SC: solution fit; MEDDPICC: DC', 'A prospect-stated must-have or required capability where product fit is unknown or known-weak per the coach''s capability knowledge. The SC''s primary risk object.', 'STATED: a must-have decision criterion or required_capabilities item flagged against coach capability docs as uncertain/weak. The requirement is the fact; the fit assessment is coach knowledge (labeled as such, never presented as a prospect fact).', ARRAY['stated']::text[], 'High for must-haves with uncertain fit; Critical for must-haves with known gaps entering selection.', 'Quote: ''It has to handle 13-period calendars per entity'' -> requirement captured; fit check flags uncertainty -> SC risk before demo.', true),
('discovery_coverage_gap', 'Discovery gaps before demo/FDC', 'Sage playbook: pre-FDC KT; pre-demo research', 'Material catalog sections remain Unknown entering a demo or proposal: the solution story is being built on unknowns. The SC-side analog of BANT gaps.', 'GAP: computable from catalog coverage: gate fields unanswered, or a gated-ON section (inventory, projects) majority-Unknown at demo scheduling.', ARRAY['gap']::text[], 'Medium at FDC scheduling; High at demo scheduling; Critical at proposal with core sections Unknown.', 'Demo on the calendar, inventory_type answered but the whole inventory section Unknown -> coverage risk + FDC agenda feed.', true),
('data_migration_complexity', 'Data migration complexity', 'SC: implementation risk', 'Stated legacy-data conditions that complicate conversion: years of history expected to migrate, dirty data admitted, multiple legacy systems, mid-year cutover expectations.', 'STATED: quotes about history expectations (''we need ten years in the new system''), data quality admissions, multi-system consolidation needs.', ARRAY['stated']::text[], 'Medium when stated and scoped; High when expectations are stated but unscoped at proposal.', 'Quote: ''All ten years of history has to come over'' -> migration-expectation risk; scoping task.', true),
('integration_feasibility', 'Critical integration unscoped', 'SC: integration risk', 'A deal-critical integration (per integrations_needed criticality) whose mechanism is unknown: no API discussion, unknown version, homegrown system on the other end.', 'STATED+GAP: integration marked critical (stated) with mechanism fields empty after FDC (gap).', ARRAY['stated','gap']::text[], 'High when must-have; Critical when must-have + homegrown/legacy endpoint stated.', 'ServiceTitan integration is conversation-over critical; nobody has discussed how -> feasibility risk before proposal.', true),
('revrec_compliance_complexity', 'Rev rec / compliance complexity', 'SC: solution risk; 606', 'Stated revenue recognition or compliance conditions of known implementation weight: POC, multi-element arrangements, audit requirements, grant compliance, retainage.', 'STATED: rev rec method, audit posture, or compliance statements matching the complexity list in coach knowledge.', ARRAY['stated']::text[], 'Medium (it is qualification-positive but delivery-relevant); High when paired with an aggressive go_live_date.', 'Quote: ''POC across 40 concurrent jobs, audited'' + go-live in 90 days -> complexity-vs-timeline risk.', true),
('scope_module_mismatch', 'Scope vs recommendation mismatch', 'SC: scoping integrity', 'required_capabilities the prospect stated are not covered by the recommended module set, or recommended modules have no stated requirement behind them (over/under-scoping).', 'GAP: computable diff between required_capabilities + gated-on sections and deal_modules recommendations.', ARRAY['gap']::text[], 'Medium either direction; High when under-scoped at proposal (quote will miss stated needs).', 'Inventory gated ON with stated requirements, no Inventory module recommended -> under-scope risk on the SC page.', true),
('demo_unvalidated_assumptions', 'Demo built on unverified assumptions', 'Sage playbook: demo etiquette; SC', 'The demo plan depends on facts that are research-sourced but never call-confirmed, or partial-status fields: demoing to a guessed configuration.', 'GAP: demo-plan inputs (entity structure, dimensions, key processes) carrying source=research unconfirmed or status=partial at demo scheduling.', ARRAY['gap']::text[], 'Medium; High when the demo''s hero scenario rests on an unconfirmed fact.', 'Demo storyline assumes 13-period calendar sourced from research, never confirmed -> validate-before-demo task + risk.', true)
